def find_literals(level_bit, pattern):
    import re
    matches = list(re.finditer(pattern, level_bit))

    if not matches:
        return None

    first_match = matches[0]
    matched_text = first_match.group()
    start_index = first_match.start()
    end_index = start_index + len(matched_text)

    return (matched_text, start_index, end_index)

